-- Declared foreign keys for deal module, added where the database lacks them
-- Generated by metaphor-schema

DO $$
BEGIN
    IF to_regclass('deal.opportunities') IS NOT NULL AND to_regclass('deal.stages') IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM pg_constraint c
        JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey)
        WHERE c.conrelid = to_regclass('deal.opportunities') AND c.contype = 'f' AND a.attname = 'stage_id'
    ) THEN
        ALTER TABLE deal.opportunities ADD CONSTRAINT fk_opportunities_stage_id FOREIGN KEY (stage_id) REFERENCES deal.stages (id) NOT VALID;
        BEGIN
            ALTER TABLE deal.opportunities VALIDATE CONSTRAINT fk_opportunities_stage_id;
        EXCEPTION WHEN foreign_key_violation THEN
            RAISE NOTICE 'fk_opportunities_stage_id left NOT VALID: stored rows of deal.opportunities reference missing rows';
        END;
    END IF;
END $$;

